    try {
      const data = await AbTestService.findOne(
        req.user.user_id,
        req.params.id
      );
      return res.status(StatusCode.OK).json(data);
    } catch (e) {
      next(e);
    }
  }

  async updateStatus(
    req: AuthenticatedRequest,
    res: Response,
    next: NextFunction
